// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint96 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = uint96(bound(amount, 1, type(uint96).max));
        Reverter reverter = new Reverter();

        address actor = address(reverter);
        vm.deal(actor, amount);

        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 balBefore = c.getBalance(actor);
        assertEq(balBefore, amount);

        vm.prank(actor);
        try c.withdrawBalance() {
            assertEq(c.getBalance(actor), balBefore);
        } catch {
            assertEq(c.getBalance(actor), balBefore);
        }
    }
}

contract Reverter {
    receive() external payable {
        revert();
    }
}
